pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0);
        vm.assume(from != address(0));
        vm.assume(caddress != address(0));
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0));
        }
        // Deploy a helper that always reverts on calls
        Reverter reverter = new Reverter();
        // Build the array where every address is the reverting contract
        address[] memory revertTos = new address[](_tos.length);
        for (uint i = 0; i < _tos.length; i++) {
            revertTos[i] = address(reverter);
        }
        // The external call to reverter will fail
        bool success;
        try c.transfer(from, caddress, revertTos, v) returns (bool ret) {
            success = true;
        } catch {
            success = false;
        }
        // Universal property: call with all callees reverting must revert the whole transaction
        // (reference reverts because it checks each sub-call; buggy ignores failures and returns true)
        assertTrue(success == false);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}

