pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 v, address from, uint8 numTos) public {
        vm.assume(numTos > 0);
        vm.assume(from != address(0));
        address[] memory tos = new address[](numTos);
        // One adversarial callee that always reverts
        Reverter reverter = new Reverter();
        tos[0] = address(reverter);
        for (uint256 i = 1; i < numTos; i++) {
            tos[i] = address(uint160(uint256(keccak256(abi.encode(i)))));
        }
        vm.prank(from);
        bool ok = false;
        try c.transfer(from, from, tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }
        // Reference always reverts -> ok is false; buggy returns true -> ok is true
        assertFalse(ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}

